import{_ as a,o,c as t,a2 as r}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/assets/10.DqR9SGP1.png",d="/newx-doc/assets/11.Ds5I1hdc.png",c="/newx-doc/assets/12.DE1_IHwa.png",b=JSON.parse('{"title":"通用方法","description":"","frontmatter":{},"headers":[],"relativePath":"vue3/util.md","filePath":"vue3/util.md","lastUpdated":null}'),l={name:"vue3/util.md"};function n(i,e,h,u,p,_){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="通用方法" tabindex="-1">通用方法 <a class="header-anchor" href="#通用方法" aria-label="Permalink to &quot;通用方法&quot;">​</a></h1><p>本小节，分享前端项目的常用方法。</p><h2 id="_1-缓存配置" tabindex="-1">1. 缓存配置 <a class="header-anchor" href="#_1-缓存配置" aria-label="Permalink to &quot;1. 缓存配置&quot;">​</a></h2><p>友情提示：</p><p>该小节，基于 <a href="https://element-plus-admin-doc.cn/guide/settings.html#%E7%BC%93%E5%AD%98%E9%85%8D%E7%BD%AE" target="_blank" rel="noreferrer">《vue element plus admin —— 项目配置「缓存配置 」》</a> 的内容修改。</p><h3 id="_1-1-说明" tabindex="-1">1.1 说明 <a class="header-anchor" href="#_1-1-说明" aria-label="Permalink to &quot;1.1 说明&quot;">​</a></h3><p>在项目中，你可以看到很多地方都使用了 <code>wsCache.set</code> 或者 <code>wsCache.get</code>，这是基于 <a href="https://github.com/wuchangming/web-storage-cache" target="_blank" rel="noreferrer">web-storage-cache</a> 进行封装，采用 <code>hook</code> 的形式。</p><p>该插件对HTML5 <code>localStorage</code> 和 <code>sessionStorage</code> 进行了扩展，添加了超时时间，序列化方法。可以直接存储 <code>json</code> 对象，同时可以非常简单的进行超时时间的设置。</p><p>本项目默认是采用 <code>sessionStorage</code> 的存储方式，如果更改，可以直接在 <a href="https://github.com/yudaocode/yudao-ui-admin-vue3/blob/master/src/hooks/web/useCache.ts" target="_blank" rel="noreferrer">useCache.ts</a> 中把 <code>type: CacheType = &#39;sessionStorage&#39;</code> 改为 <code>type: CacheType = &#39;localStorage&#39;</code>，这样项目中的所有用到的地方，都会变成该方式进行数据存储。</p><p>如果只想单个更改，可以传入存储类型 <code>const { wsCache } = useCache(&#39;localStorage&#39;)</code>，既可只适用当前存储对象。</p><p>注意：</p><p>更改完默认存储方式后，需要清除浏览器缓存并重新登录，以免造成不可描述的问题。</p><h3 id="_1-2-示例" tabindex="-1">1.2 示例 <a class="header-anchor" href="#_1-2-示例" aria-label="Permalink to &quot;1.2 示例&quot;">​</a></h3><p><img src="'+s+'" alt="wsCache 示例"></p><h2 id="_2-message-对象" tabindex="-1">2. <code>message</code> 对象 <a class="header-anchor" href="#_2-message-对象" aria-label="Permalink to &quot;2. `message` 对象&quot;">​</a></h2><h3 id="_2-1-说明" tabindex="-1">2.1 说明 <a class="header-anchor" href="#_2-1-说明" aria-label="Permalink to &quot;2.1 说明&quot;">​</a></h3><p><code>message</code> 对象，由 <a href="https://github.com/yudaocode/yudao-ui-admin-vue3/blob/master/src/hooks/web/useMessage.ts" target="_blank" rel="noreferrer">src/hooks/web/useMessage.ts</a> 实现，基于 ElMessage、ElMessageBox、ElNotification 封装，用于做消息提示、通知提示、对话框提醒、二次确认等。</p><h3 id="_2-2-示例" tabindex="-1">2.2 示例 <a class="header-anchor" href="#_2-2-示例" aria-label="Permalink to &quot;2.2 示例&quot;">​</a></h3><p><img src="'+d+'" alt="message 示例"></p><h2 id="_3-download-对象" tabindex="-1">3. <code>download</code> 对象 <a class="header-anchor" href="#_3-download-对象" aria-label="Permalink to &quot;3. `download` 对象&quot;">​</a></h2><h3 id="_3-1-说明" tabindex="-1">3.1 说明 <a class="header-anchor" href="#_3-1-说明" aria-label="Permalink to &quot;3.1 说明&quot;">​</a></h3><p><code>$download</code> 对象，由 <a href="https://github.com/yudaocode/yudao-ui-admin-vue3/blob/master/src/utils/download.ts" target="_blank" rel="noreferrer"><code>util/download.ts</code></a> 实现，用于 Excel、Word、Zip、HTML 等类型的文件下载。</p><h3 id="_3-2-示例" tabindex="-1">3.2 示例 <a class="header-anchor" href="#_3-2-示例" aria-label="Permalink to &quot;3.2 示例&quot;">​</a></h3><p><img src="'+c+'" alt="download 示例"></p>',24)])])}const g=a(l,[["render",n]]);export{b as __pageData,g as default};
